import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong individual effects (p < 0.01)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            # For clinical features, use t-test effect size
            t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * len(feats.y))
            if abs(t_stat) > 2.0:
                strong_features.append((fid, abs(t_stat)))
        else:
            # For non-clinical, use mutual information
            mi = mutual_info_classif(feats.x[:, i:i+1], feats.y)[0]
            if mi > 0.05:
                strong_features.append((fid, mi))

    # Sort by strength
    strong_features.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated with r > 0.6)
    selected = []
    used = set()
    for fid, _ in strong_features:
        if fid in used:
            continue
        # Check correlations with already selected features
        is_duplicate = False
        for selected_fid in selected:
            col_a = feats.column(selected_fid)
            col_b = feats.column(fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]) > 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            selected.append(fid)
            used.add(fid)
            if len(selected) >= MAX_DRIVERS:
                break

    # If no strong features, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Limit to at most 4 drivers as per checker report
    drivers = tuple(selected[:4])

    # Build the design with minimal complexity
    columns = list(drivers)

    # Create interaction terms for top features (at most 1 interaction)
    products = []
    if len(drivers) >= 2:
        products = [(drivers[0], drivers[1])]

    # Simple weighted score using top feature
    loadings = {drivers[0]: 1.0}

    return Design(drivers=drivers, columns=tuple(columns), products=tuple(products), loadings=loadings)

